-- Clean bootstrap 019: final exchange-rate model, finance and protected admin reports.
CREATE TABLE IF NOT EXISTS public.exchange_rates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),base_currency text NOT NULL CHECK(base_currency IN('CDF','USD')),quote_currency text NOT NULL CHECK(quote_currency IN('CDF','USD')),rate numeric(18,6) NOT NULL CHECK(rate>0),valid_from timestamptz NOT NULL DEFAULT now(),valid_until timestamptz,is_active boolean NOT NULL DEFAULT true,created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(base_currency<>quote_currency),CHECK(valid_until IS NULL OR valid_until>valid_from));
CREATE UNIQUE INDEX IF NOT EXISTS unique_active_exchange_rate ON public.exchange_rates(base_currency,quote_currency) WHERE is_active;
INSERT INTO public.exchange_rates(base_currency,quote_currency,rate,is_active) VALUES('USD','CDF',2500,true) ON CONFLICT(base_currency,quote_currency) WHERE is_active DO NOTHING;
CREATE TABLE IF NOT EXISTS public.cash_registers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,currency text NOT NULL CHECK(currency IN('CDF','USD')),opening_balance numeric(18,2) NOT NULL DEFAULT 0,current_balance numeric(18,2) NOT NULL DEFAULT 0,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.cash_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cash_register_id uuid NOT NULL REFERENCES public.cash_registers(id),movement_type text NOT NULL CHECK(movement_type IN('in','out')),amount numeric(18,2) NOT NULL CHECK(amount>0),currency text NOT NULL CHECK(currency IN('CDF','USD')),reason text NOT NULL,created_by uuid REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.bank_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_name text NOT NULL,bank_name text NOT NULL,account_number text,currency text NOT NULL CHECK(currency IN('CDF','USD')),current_balance numeric(18,2) NOT NULL DEFAULT 0,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.bank_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bank_account_id uuid NOT NULL REFERENCES public.bank_accounts(id),transaction_type text NOT NULL CHECK(transaction_type IN('credit','debit')),amount numeric(18,2) NOT NULL CHECK(amount>0),currency text NOT NULL CHECK(currency IN('CDF','USD')),reference text,description text,created_by uuid REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.accounting_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entry_date date NOT NULL DEFAULT current_date,label text NOT NULL,debit numeric(18,2) NOT NULL DEFAULT 0,credit numeric(18,2) NOT NULL DEFAULT 0,currency text NOT NULL CHECK(currency IN('CDF','USD')),related_entity_type text,related_entity_id uuid,created_by uuid REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(debit>=0 AND credit>=0 AND (debit=0 OR credit=0)));
CREATE TABLE IF NOT EXISTS public.ai_insights(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),insight_type text NOT NULL,title text NOT NULL,description text NOT NULL,severity text NOT NULL DEFAULT 'info',payload jsonb NOT NULL DEFAULT '{}'::jsonb,generated_at timestamptz NOT NULL DEFAULT now());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['exchange_rates','cash_registers','cash_movements','bank_accounts','bank_transactions','accounting_entries','ai_insights'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('DROP POLICY IF EXISTS finance_access ON public.%I',t); EXECUTE format('CREATE POLICY finance_access ON public.%I FOR SELECT TO authenticated USING(public.is_admin() OR public.has_role(''comptable''))',t); END LOOP; END $$;

CREATE OR REPLACE VIEW public.admin_dashboard_realtime WITH(security_invoker=true) AS SELECT now() generated_at,(SELECT count(*) FROM public.sales_orders) order_count,(SELECT COALESCE(sum(total_amount),0) FROM public.sales_orders WHERE order_status<>'cancelled') gross_sales,(SELECT count(*) FROM public.customers WHERE is_active) active_customers,(SELECT count(*) FROM public.inventory_stock WHERE quantity<=reorder_level) low_stock_items,(SELECT COALESCE(sum(amount),0) FROM public.expenses WHERE status<>'rejected') expenses,(SELECT COALESCE(sum(amount),0) FROM public.payments) payments;
CREATE MATERIALIZED VIEW IF NOT EXISTS public.admin_daily_report AS SELECT current_date period_start,* FROM public.admin_dashboard_realtime WITH NO DATA;
CREATE MATERIALIZED VIEW IF NOT EXISTS public.admin_weekly_report AS SELECT date_trunc('week',current_date)::date period_start,* FROM public.admin_dashboard_realtime WITH NO DATA;
CREATE MATERIALIZED VIEW IF NOT EXISTS public.admin_monthly_report AS SELECT date_trunc('month',current_date)::date period_start,* FROM public.admin_dashboard_realtime WITH NO DATA;
CREATE MATERIALIZED VIEW IF NOT EXISTS public.admin_quarterly_report AS SELECT date_trunc('quarter',current_date)::date period_start,* FROM public.admin_dashboard_realtime WITH NO DATA;
CREATE MATERIALIZED VIEW IF NOT EXISTS public.admin_annual_report AS SELECT date_trunc('year',current_date)::date period_start,* FROM public.admin_dashboard_realtime WITH NO DATA;
DO $$ BEGIN REFRESH MATERIALIZED VIEW public.admin_daily_report; REFRESH MATERIALIZED VIEW public.admin_weekly_report; REFRESH MATERIALIZED VIEW public.admin_monthly_report; REFRESH MATERIALIZED VIEW public.admin_quarterly_report; REFRESH MATERIALIZED VIEW public.admin_annual_report; END $$;
REVOKE ALL ON public.admin_dashboard_realtime,public.admin_daily_report,public.admin_weekly_report,public.admin_monthly_report,public.admin_quarterly_report,public.admin_annual_report FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.assert_admin() RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role('admin') THEN RAISE EXCEPTION 'Admin role required' USING ERRCODE='42501'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.get_admin_dashboard() RETURNS SETOF public.admin_dashboard_realtime LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.assert_admin(); RETURN QUERY SELECT * FROM public.admin_dashboard_realtime; END $$;
CREATE OR REPLACE FUNCTION public.get_daily_report() RETURNS SETOF public.admin_daily_report LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.assert_admin(); RETURN QUERY SELECT * FROM public.admin_daily_report; END $$;
CREATE OR REPLACE FUNCTION public.get_weekly_report() RETURNS SETOF public.admin_weekly_report LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.assert_admin(); RETURN QUERY SELECT * FROM public.admin_weekly_report; END $$;
CREATE OR REPLACE FUNCTION public.get_monthly_report() RETURNS SETOF public.admin_monthly_report LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.assert_admin(); RETURN QUERY SELECT * FROM public.admin_monthly_report; END $$;
CREATE OR REPLACE FUNCTION public.get_quarterly_report() RETURNS SETOF public.admin_quarterly_report LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.assert_admin(); RETURN QUERY SELECT * FROM public.admin_quarterly_report; END $$;
CREATE OR REPLACE FUNCTION public.get_annual_report() RETURNS SETOF public.admin_annual_report LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.assert_admin(); RETURN QUERY SELECT * FROM public.admin_annual_report; END $$;
GRANT EXECUTE ON FUNCTION public.get_admin_dashboard(),public.get_daily_report(),public.get_weekly_report(),public.get_monthly_report(),public.get_quarterly_report(),public.get_annual_report() TO authenticated;
DROP POLICY IF EXISTS accounting_entries_manage ON public.accounting_entries;
CREATE POLICY accounting_entries_manage ON public.accounting_entries FOR ALL TO authenticated USING(public.is_admin() OR public.has_role('comptable')) WITH CHECK(public.is_admin() OR public.has_role('comptable'));
DROP POLICY IF EXISTS cash_registers_manage ON public.cash_registers;
CREATE POLICY cash_registers_manage ON public.cash_registers FOR ALL TO authenticated USING(public.is_admin() OR public.has_role('comptable')) WITH CHECK(public.is_admin() OR public.has_role('comptable'));
DROP POLICY IF EXISTS cash_movements_manage ON public.cash_movements;
CREATE POLICY cash_movements_manage ON public.cash_movements FOR ALL TO authenticated USING(public.is_admin() OR public.has_role('comptable')) WITH CHECK(public.is_admin() OR public.has_role('comptable'));
DROP POLICY IF EXISTS bank_accounts_manage ON public.bank_accounts;
CREATE POLICY bank_accounts_manage ON public.bank_accounts FOR ALL TO authenticated USING(public.is_admin() OR public.has_role('comptable')) WITH CHECK(public.is_admin() OR public.has_role('comptable'));
DROP POLICY IF EXISTS bank_transactions_manage ON public.bank_transactions;
CREATE POLICY bank_transactions_manage ON public.bank_transactions FOR ALL TO authenticated USING(public.is_admin() OR public.has_role('comptable')) WITH CHECK(public.is_admin() OR public.has_role('comptable'));
CREATE OR REPLACE FUNCTION public.get_sales_by_category(start_date timestamptz) RETURNS TABLE(category_name text,total_sales numeric,total_quantity bigint) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT COALESCE(c.name,'Sans catégorie'),COALESCE(sum(oi.line_total),0),COALESCE(sum(oi.quantity),0)::bigint FROM public.order_items oi JOIN public.sales_orders so ON so.id=oi.order_id JOIN public.products p ON p.id=oi.product_id LEFT JOIN public.product_categories c ON c.id=p.category_id WHERE so.order_date>=start_date GROUP BY c.name ORDER BY total_sales DESC $$;
CREATE OR REPLACE FUNCTION public.get_admin_sales_report(p_start timestamptz,p_end timestamptz) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.assert_admin(); RETURN (SELECT jsonb_build_object('orders',count(*),'revenue',COALESCE(sum(total_amount),0),'period_start',p_start,'period_end',p_end) FROM public.sales_orders WHERE order_date BETWEEN p_start AND p_end); END $$;
CREATE OR REPLACE FUNCTION public.get_admin_finance_report(p_start timestamptz,p_end timestamptz) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.assert_admin(); RETURN jsonb_build_object('payments',(SELECT COALESCE(sum(amount),0) FROM public.payments WHERE payment_date BETWEEN p_start AND p_end),'expenses',(SELECT COALESCE(sum(amount),0) FROM public.expenses WHERE expense_date BETWEEN p_start::date AND p_end::date),'purchases',(SELECT COALESCE(sum(total_amount),0) FROM public.purchases WHERE ordered_at BETWEEN p_start AND p_end)); END $$;
CREATE OR REPLACE FUNCTION public.get_admin_operations_report(p_start timestamptz,p_end timestamptz) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.assert_admin(); RETURN jsonb_build_object('low_stock',(SELECT count(*) FROM public.inventory_stock WHERE quantity<=reorder_level),'deliveries',(SELECT count(*) FROM public.deliveries WHERE created_at BETWEEN p_start AND p_end),'receivables',(SELECT COALESCE(sum(total_amount-amount_paid),0) FROM public.invoices WHERE created_at BETWEEN p_start AND p_end)); END $$;
CREATE OR REPLACE FUNCTION public.get_admin_total_report(p_start timestamptz,p_end timestamptz) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.assert_admin(); RETURN jsonb_build_object('sales',public.get_admin_sales_report(p_start,p_end),'finance',public.get_admin_finance_report(p_start,p_end),'operations',public.get_admin_operations_report(p_start,p_end)); END $$;
REVOKE ALL ON FUNCTION public.get_admin_sales_report(timestamptz,timestamptz),public.get_admin_finance_report(timestamptz,timestamptz),public.get_admin_operations_report(timestamptz,timestamptz),public.get_admin_total_report(timestamptz,timestamptz) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_admin_sales_report(timestamptz,timestamptz),public.get_admin_finance_report(timestamptz,timestamptz),public.get_admin_operations_report(timestamptz,timestamptz),public.get_admin_total_report(timestamptz,timestamptz) TO authenticated;
